1	/**
2	 * Resolves the request's `Actor` for a given org slug, or throws
3	 * `unauthorized` / `forbidden`. Every Server Action starts here.
4	 *
5	 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
6	 * this module is the seam between "there is an HTTP request with a cookie"
7	 * and the rest of the app, which knows nothing about requests.
8	 */
9	import { getSessionPrincipal } from "@/lib/session";
10	import { assertOrgScope } from "@/lib/tenant";
11	import { findOrgById } from "@/server/repositories/organization-repository";
12	import { resolveActorForOrg } from "@/server/services/session-service";
13	import type { OrgId } from "@/types/common";
14	import type { Actor } from "@/types/member";
15	
16	/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
17	export class UnauthorizedError extends Error {
18	  readonly code = "unauthorized" as const;
19	
20	  constructor(message = "Sign in to continue.") {
21	    super(message);
22	    this.name = "UnauthorizedError";
23	  }
24	}
25	
26	/** Thrown when the session is valid but has no membership in the target org. */
27	export class NoMembershipError extends Error {
28	  readonly code = "forbidden" as const;
29	
30	  constructor(readonly orgSlug: string) {
31	    super(`You are not a member of "${orgSlug}".`);
32	    this.name = "NoMembershipError";
33	  }
34	}
35	
36	/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
37	export async function getActor(orgSlug: string): Promise<Actor> {
38	  const principal = await getSessionPrincipal();
39	  if (principal === null) throw new UnauthorizedError();
40	
41	  const actor = await resolveActorForOrg(principal, orgSlug);
42	  if (actor === null) throw new NoMembershipError(orgSlug);
43	
44	  return actor;
45	}
46	
47	/** Non-throwing variant, for layouts that render a signed-out state. */
48	export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
49	  try {
50	    return await getActor(orgSlug);
51	  } catch (error) {
52	    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
53	      return null;
54	    }
55	    throw error;
56	  }
57	}
58	
59	/**
60	 * The `Actor` for an org already identified by id — used by Route Handlers
61	 * that receive an `orgId` in the payload rather than a slug in the path. The
62	 * session's active org must match, which `assertOrgScope()` enforces.
63	 *
64	 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
65	 * with a single repository lookup rather than by widening that signature —
66	 * the slug is the only handle the session layer knows.
67	 */
68	export async function requireActorFor(orgId: OrgId): Promise<Actor> {
69	  const principal = await getSessionPrincipal();
70	  if (principal === null) throw new UnauthorizedError();
71	  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);
72	
73	  const org = await findOrgById(orgId);
74	  if (org === null) throw new NoMembershipError(orgId);
75	
76	  const actor = await resolveActorForOrg(principal, org.slug);
77	  if (actor === null) throw new NoMembershipError(org.slug);
78	
79	  assertOrgScope(actor, orgId);
80	  return actor;
81	}
